package android.os;import java.util.concurrent.*;public class Handler{public static final java.util.Queue<Runnable> Q=new ConcurrentLinkedQueue<>();public Handler(Looper l){}public boolean post(Runnable r){Q.add(r);return true;}public boolean postDelayed(Runnable r,long n){return true;}public void removeCallbacks(Runnable r){Q.removeIf(x->x==r);}public static void drain(){Runnable r;while((r=Q.poll())!=null)r.run();}}